/// <reference path="./worker-configuration.d.ts" />
import { createRemoteJWKSet, jwtVerify, type JWTVerifyGetKey } from 'jose';
import { z } from 'zod';
import { opaqueTokenSchema } from '../../contracts/v1/auth';
import { failure, GatewayError, json } from '../../server/http';
import { selectRoute, type BotRoute } from './routes';
import { boundedBytes, parseJson } from './transport';

// The binding interface is generated by Wrangler; this narrower fetch surface also
// lets tests supply a deterministic transport without connecting to the real bot.
export type BotGatewayEnv = Omit<BotGatewayBindings, 'BOT_API'> & {
  BOT_API: { fetch(request: Request): Promise<Response> };
};
const keySets = new Map<string, ReturnType<typeof createRemoteJWKSet>>();
const emptyQuery = z.object({}).strict();
const imageTypes = ['image/png', 'image/jpeg', 'image/webp', 'image/gif'];

async function authenticate(request: Request, env: BotGatewayEnv, jwks?: JWTVerifyGetKey): Promise<string> {
  if (!/^https:\/\/[a-z0-9-]+\.cloudflareaccess\.com$/.test(env.ACCESS_TEAM_DOMAIN) ||
      !env.BACKEND_ACCESS_AUDIENCE || !env.GATEWAY_SERVICE_ID ||
      !['production', 'preview'].includes(env.ENVIRONMENT)) {
    throw new GatewayError(503, 'NOT_CONFIGURED', 'The backend connection has not been configured.');
  }
  const assertion = request.headers.get('Cf-Access-Jwt-Assertion');
  if (!assertion || assertion.length > 16384 || request.headers.get('X-WO-Environment') !== env.ENVIRONMENT) {
    throw new GatewayError(401, 'AUTH_REQUIRED', 'Service authentication is required.');
  }
  try {
    let resolver = jwks ?? keySets.get(env.ACCESS_TEAM_DOMAIN);
    if (!resolver) {
      const remoteKeys = createRemoteJWKSet(new URL(env.ACCESS_TEAM_DOMAIN + '/cdn-cgi/access/certs'), { timeoutDuration: 5000, cooldownDuration: 30000 });
      keySets.set(env.ACCESS_TEAM_DOMAIN, remoteKeys);
      resolver = remoteKeys;
    }
    const { payload } = await jwtVerify(assertion, resolver, {
      issuer: env.ACCESS_TEAM_DOMAIN, audience: env.BACKEND_ACCESS_AUDIENCE,
      algorithms: ['RS256'], requiredClaims: ['exp', 'iat'], clockTolerance: 5,
    });
    if (payload.common_name !== env.GATEWAY_SERVICE_ID || typeof payload.iat !== 'number' || payload.iat > Date.now() / 1000 + 5) throw new Error();
    return assertion;
  } catch { throw new GatewayError(401, 'AUTH_REQUIRED', 'Service identity could not be verified.'); }
}

function requestHeaders(request: Request, env: BotGatewayEnv, assertion?: string): Headers {
  const headers = new Headers({ Accept: 'application/json' });
  if (!assertion) return headers;
  headers.set('Cf-Access-Jwt-Assertion', assertion);
  headers.set('X-WO-Environment', env.ENVIRONMENT);
  headers.set('X-Request-Id', crypto.randomUUID());
  const session = request.headers.get('X-WO-Admin-Session');
  if (session) {
    if (!opaqueTokenSchema.safeParse(session).success) throw new GatewayError(400, 'INVALID_SESSION', 'The session credential is invalid.');
    headers.set('X-WO-Admin-Session', session);
  }
  const key = request.headers.get('Idempotency-Key');
  if (key) {
    if (!/^[a-zA-Z0-9_-]{16,100}$/.test(key)) throw new GatewayError(400, 'INVALID_REQUEST_ID', 'The request identifier is invalid.');
    headers.set('Idempotency-Key', key);
  }
  return headers;
}

async function forward(request: Request, env: BotGatewayEnv, route: BotRoute, url: URL, headers: Headers): Promise<Response> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 15000);
  const cancel = () => controller.abort();
  request.signal.addEventListener('abort', cancel, { once: true });
  try {
    if (request.signal.aborted) controller.abort();
    const signal = controller.signal;
    let body: Uint8Array<ArrayBuffer> | undefined;
    if (route.bodyLimit) {
      if (request.headers.has('Content-Encoding')) throw new GatewayError(415, 'ENCODING_DENIED', 'Encoded request bodies are not supported.');
      body = await boundedBytes(request, route.bodyLimit, signal);
      if (route.media) {
        const type = request.headers.get('Content-Type') ?? '';
        const metadata = request.headers.get('X-WO-Media') ?? '';
        if (!imageTypes.includes(type) || !body.byteLength || metadata.length > 2048 || !z.object({
          slug: z.string().max(96).regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/), purpose: z.enum(['cover', 'body', 'gallery']),
          fileName: z.string().min(1).max(160), mimeType: z.literal(type),
        }).strict().safeParse(parseJson(new TextEncoder().encode(metadata))).success) throw new GatewayError(400, 'INVALID_IMAGE', 'The image request is invalid.');
        headers.set('Content-Type', type); headers.set('X-WO-Media', metadata);
      } else {
        if (!/^application\/json(?:\s*;.*)?$/i.test(request.headers.get('Content-Type') ?? '')) throw new GatewayError(415, 'JSON_REQUIRED', 'Use a JSON request.');
        const input = route.input?.safeParse(parseJson(body));
        if (!input?.success) throw new GatewayError(400, 'INVALID_INPUT', 'The request fields are invalid.');
        body = new TextEncoder().encode(JSON.stringify(input.data));
        headers.set('Content-Type', 'application/json');
      }
    } else if (request.body) throw new GatewayError(400, 'BODY_DENIED', 'This read does not accept a body.');
    const target = new URL('http://127.0.0.1:25599');
    target.pathname = url.pathname; target.search = url.search;
    const upstream = await env.BOT_API.fetch(new Request(target, { method: request.method, headers, body, redirect: 'manual', signal }));
    if (!upstream.ok) {
      if (upstream.status === 403 && url.pathname === '/v1/admin/auth/discord/callback' && upstream.headers.get('Content-Type')?.startsWith('application/json')) {
        let enrollmentRequired = false;
        try {
          const value = z.object({ code: z.string().optional(), error: z.object({ code: z.string().optional() }).optional() }).parse(parseJson(await boundedBytes(upstream, 4096, signal)));
          enrollmentRequired = value.code === 'ENROLLMENT_REQUIRED' || value.error?.code === 'ENROLLMENT_REQUIRED';
        } catch { signal.throwIfAborted(); }
        if (enrollmentRequired) throw new GatewayError(403, 'ENROLLMENT_REQUIRED', 'Run /dashboard enable in the Discord server before signing in.');
      }
      void upstream.body?.cancel().catch(() => undefined);
      const code = !route.public && [400, 401, 403, 404, 409, 413, 422, 429, 503].includes(upstream.status) ? upstream.status : route.public && upstream.status === 503 ? 503 : 502;
      // Never return upstream error text, cookies, redirects, or arbitrary headers.
      throw new GatewayError(code, 'BACKEND_UNAVAILABLE', 'The backend request could not be completed.');
    }
    try {
      const bytes = await boundedBytes(upstream, route.responseLimit, signal);
      if (route.media && !route.output) {
        const type = upstream.headers.get('Content-Type') ?? '';
        if (!imageTypes.includes(type)) throw new Error();
        return new Response(bytes, { headers: { 'Content-Type': type, 'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff', 'Content-Security-Policy': "default-src 'none'; sandbox", 'Referrer-Policy': 'no-referrer' } });
      }
      if (!/^application\/json(?:\s*;.*)?$/i.test(upstream.headers.get('Content-Type') ?? '')) throw new Error();
      const output = route.output?.safeParse(parseJson(bytes));
      if (!output?.success) throw new Error();
      return json(output.data, 200, route.public ? 'public, max-age=15, must-revalidate' : 'no-store');
    } catch (error) {
      if (signal.aborted) throw error;
      throw new GatewayError(502, 'INVALID_RESPONSE', 'The backend returned an unsupported response.');
    }
  } finally {
    clearTimeout(timer);
    request.signal.removeEventListener('abort', cancel);
  }
}

export async function handleBotGateway(request: Request, env: BotGatewayEnv, dependencies: { jwks?: JWTVerifyGetKey } = {}): Promise<Response> {
  try {
    const url = new URL(request.url);
    const route = selectRoute(request.method, url.pathname);
    if (!route || url.hash) throw new GatewayError(404, 'NOT_FOUND', 'This route is not available.');
    const assertion = route.public ? undefined : await authenticate(request, env, dependencies.jwks);
    const entries = [...url.searchParams];
    if (new Set(entries.map(([name]) => name)).size !== entries.length || !(route.query ?? emptyQuery).safeParse(Object.fromEntries(entries)).success) throw new GatewayError(400, 'INVALID_QUERY', 'The query fields are invalid.');
    return await forward(request, env, route, url, requestHeaders(request, env, assertion));
  } catch (error) { return failure(error); }
}

export default {
  fetch(request: Request, env: BotGatewayEnv): Promise<Response> {
    return handleBotGateway(request, env);
  },
};
